    public GoodsReceipt testCreate() throws Throwable {
    GoodsReceipt entity = null;

    LOGGER.info( "GoodsReceiptTest:testCreate()" );
    LOGGER.info( "-- Attempting to create a GoodsReceipt");

    StringBuilder msg = new StringBuilder( "-- Failed to create a GoodsReceipt" );

    try {
        entity = service.createGoodsReceipt( generateNewCommand() );
        assertNotNull( entity, msg.toString() );

        theId = entity.getGoodsReceiptId();
        assertNotNull( theId, msg.toString() + " Contains a null primary key" );

        LOGGER.info( "-- Successfully created a GoodsReceipt with primary key" + theId );
    }
    catch (Exception e)  {
        LOGGER.warning( unexpectedErrorMsg );
        LOGGER.warning( msg.toString() + entity );

        throw e;
    }
    return entity;
}

