    /**
     * Tests getting all GoodsReceipts.
     *
     * @return    Collection
     */
    public List<GoodsReceipt> testGetAll() throws Throwable {
    LOGGER.info( "GoodsReceiptTest:testGetAll() - Retrieving Collection of GoodsReceipts:" );

    StringBuilder msg = new StringBuilder( "-- Failed to get all GoodsReceipt : " );
    List<GoodsReceipt> collection  = null;

    try {
        // call the static get method on the GoodsReceiptService
        collection = service.getAllGoodsReceipt();

        if ( collection == null || collection.size() == 0 ) {
            LOGGER.warning( unexpectedErrorMsg );
            LOGGER.warning( "-- " + msg.toString() + " Empty collection returned."  );
        }
        else {
            // Now print out the values
            GoodsReceipt currEntity  = null;
            Iterator<GoodsReceipt> iter = collection.iterator();

            while( iter.hasNext() ) {
                // Retrieve the entity
                currEntity = iter.next();

                assertNotNull( currEntity,"-- null value object in Collection." );
                assertNotNull( currEntity.getGoodsReceiptId(), "-- value object in Collection has a null primary key" );

                LOGGER.info( " - " + currEntity.toString() );
            }
        }
    }
    catch ( Throwable e ){
        LOGGER.warning( unexpectedErrorMsg );
        LOGGER.warning( msg.toString() );

        throw e;
    }

    return( collection );
}

